    // A fixed, committed debug keystore (app/debug.keystore) instead of the
    // auto-generated one. Without this, every CI build (and every machine)
    // signs with a different random key, so Android treats each build as a
    // different app and refuses to install over a previous one ("App not
    // installed"). Same signature every time = installs update cleanly, and
    // it's what lets Play Protect build any trust in the app over repeated
    // installs instead of starting from zero each time.
    signingConfigs {
        getByName("debug") {
            storeFile = file("debug.keystore")
            storePassword = "android"
            keyAlias = "androiddebugkey"
            keyPassword = "android"
        }
    }

    buildTypes {
        getByName("debug") {
            signingConfig = signingConfigs.getByName("debug")
        }
    }

    buildFeatures {
        compose = true
        buildConfig = true
    }

    packaging {
        resources {
            excludes += "/META-INF/{AL2.0,LGPL2.1}"
        }
    }
}

